import java.io.*;
import java.util.*;

public class CF1096G_Variant4 {
    static final int MODULUS = 998244353;
    static long[] wPre, wPreInv;
    static long powMod(int base, int exp) {
        long res = 1;
        long b = base;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1)
                res = (res * b) % MODULUS;
            b = (b * b) % MODULUS;
            e >>= 1;
        }
        return res;
    }
    static void prepareRoots() {
        wPre = new long[21];
        wPreInv = new long[21];
        for (int h = 0; h <= 20; h++) {
            wPre[h] = powMod(3, (MODULUS - 1) >> h);
            wPreInv[h] = powMod(3, (MODULUS - 1) - ((MODULUS - 1) >> h));
        }
    }
    static void fftTransform(int[] data, int len, boolean inv) {
        for (int i = 1, j = 0; i < len; i++) {
            int mask = len;
            do
                j ^= mask >>= 1;
            while ((j & mask) == 0);
            if (i < j) {
                int tmp = data[i]; data[i] = data[j]; data[j] = tmp;
            }
        }
        for (int h = 0, size; (size = 1 << h) < len; h++) {
            long root = inv ? wPreInv[h + 1] : wPre[h + 1];
            for (int startIdx = 0; startIdx < len; startIdx += size * 2) {
                long w = 1;
                for (int j = 0; j < size; j++) {
                    int leftIdx = startIdx + j, rightIdx = leftIdx + size;
                    long u = data[leftIdx], v = data[rightIdx] * w;
                    data[leftIdx] = (int)((u + v) % MODULUS);
                    data[rightIdx] = (int)((u - v + MODULUS) % MODULUS);
                    w = w * root % MODULUS;
                }
            }
        }
    }
    public static void main(String[] args) throws IOException {
        prepareRoots();
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int nHalfVal = Integer.parseInt(st.nextToken()) / 2;
        int kCount = Integer.parseInt(st.nextToken());
        int sizeN = 1;
        while (sizeN < nHalfVal * 9 + 1)
            sizeN <<= 1;
        int[] arrayData = new int[sizeN];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < kCount; i++) {
            int d = Integer.parseInt(st.nextToken());
            arrayData[d] = 1;
        }
        fftTransform(arrayData, sizeN, false);
        for (int i = 0; i < sizeN; i++)
            arrayData[i] = (int) powMod(arrayData[i], nHalfVal);
        fftTransform(arrayData, sizeN, true);
        long invN = powMod(sizeN, MODULUS - 2);
        long totalSum = 0;
        for (int i = 0; i < sizeN; i++) {
            arrayData[i] = (int) (arrayData[i] * invN % MODULUS);
            if (arrayData[i] < 0)
                arrayData[i] += MODULUS;
        }
        for (int i = 0; i <= nHalfVal * 9; i++) {
            long val = arrayData[i];
            totalSum = (totalSum + val * val) % MODULUS;
        }
        System.out.println(totalSum);
    }
}
